const tabId = 1148881640;
const actualResults = await browserjs(tabId, () => {
  // Let's find elements under the search results section
  const main = document.querySelector('main');
  if (!main) return [];

  // Find all links inside main that are actual search results
  // Let's check headers or items
  const resultCards = Array.from(main.querySelectorAll('h3, [data-testid*="result"], .search-result, article')).map(el => {
    const link = el.querySelector('a') || (el.tagName === 'A' ? el : null);
    return {
      tag: el.tagName,
      text: el.innerText?.trim(),
      href: link?.href || el.closest('a')?.href || null
    };
  });
  return resultCards;
});
console.log(JSON.stringify(actualResults.slice(0, 20), null, 2));

