const pageData = await browserjs(tabId, () => {
  // Look for initial state, chart data, or script tags
  const scripts = Array.from(document.querySelectorAll('script')).map(s => s.textContent || s.innerText);
  const dataScript = scripts.find(s => s.includes('highcharts') || s.includes('window.__') || s.includes('marketData') || s.includes('"revenue"') || s.includes('"forecast"'));

  // Also check if highcharts instances exist
  const highcharts = window.Highcharts ? window.Highcharts.charts.filter(Boolean).map(c => ({
    title: c.title?.textStr,
    series: c.series?.map(s => ({ name: s.name, data: s.data?.map(d => ({ x: d.x, y: d.y, name: d.name })) }))
  })) : null;

  return {
    highcharts,
    hasDataScript: !!dataScript,
    dataScriptPreview: dataScript ? dataScript.slice(0, 500) : null
  };
});
console.log(JSON.stringify(pageData, null, 2));

