const tabId = 1148881640;

const pagesToRead = [
  { name: "Artificial Intelligence", url: "https://www.statista.com/outlook/tmo/artificial-intelligence/china/" },
  { name: "eCommerce", url: "https://www.statista.com/outlook/emo/ecommerce/china/" },
  { name: "Advertising", url: "https://www.statista.com/outlook/amo/advertising/china/" },
  { name: "Payments", url: "https://www.statista.com/outlook/fmo/payments/china/" },
  { name: "Cloud Computing", url: "https://www.statista.com/outlook/tmo/cloud-computing/china/" },
  { name: "Digital Health", url: "https://www.statista.com/outlook/hmo/digital-health/china/" }
];

const insights = [];

for (const p of pagesToRead) {
  await tool.navigate({ tabId, url: p.url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load" });

  const extracted = await browserjs(tabId, () => {
    // Look for highlights, analyst opinion, text
    const text = document.querySelector('main')?.innerText || document.body.innerText;

    // Extract sections like Highlights, Analyst Opinion, Overview
    const analystOpinionMatch = text.match(/Analyst Opinion[\s\S]*?(?=Methodology|Key Market Indicators|Notes:|$)/i);
    const highlightsMatch = text.match(/Highlights[\s\S]*?(?=Currency|Limited Access|$)/i);

    return {
      title: document.title,
      highlights: highlightsMatch ? highlightsMatch[0].slice(0, 1500) : null,
      analystOpinion: analystOpinionMatch ? analystOpinionMatch[0].slice(0, 2000) : null,
      fullSnippet: text.slice(0, 2500)
    };
  });

  insights.push({ name: p.name, url: p.url, ...extracted });
}

console.log(JSON.stringify(insights.map(i => ({
  name: i.name,
  highlights: i.highlights,
  analystOpinion: i.analystOpinion
})), null, 2));

